/* Электронная подпись: документ или книга → байты теми же писателями, что «Сохранить» (документ.собрать / книга.собрать) →
   подпись CAdES-BES средством подписи на компьютере человека (эп.подписать: страница сама спрашивает подтверждение,
   PIN спрашивает средство) → файл и .sig — архивом или по отдельности. Проверка: эп.проверить по паре «файл + подпись». */
const ВТАБЛИЦАХ = typeof книга !== 'undefined';
const ЗЕЛЁНЫЙ = '#2b8a3e', КРАСНЫЙ = '#c92a2a', СЕРЫЙ = '#868e96', ЖЁЛТЫЙ = '#e67700';
let сертификаты = [];
const кДате = d => { if(!d) return '—'; const x = d instanceof Date ? d : new Date(d); return isNaN(x) ? '—' : String(x.getDate()).padStart(2, '0') + '.' + String(x.getMonth() + 1).padStart(2, '0') + '.' + x.getFullYear(); };
const кВремени = d => { const x = d instanceof Date ? d : new Date(d); return isNaN(x) ? '—' : кДате(x) + ' ' + String(x.getHours()).padStart(2, '0') + ':' + String(x.getMinutes()).padStart(2, '0'); };
async function безСбоя(f){ try { return await f(); } catch(e){ панель.сообщение(e.message); return null; } }

/* «CN=…, SN=…, G=…, O=…» → кто и от какой организации. В квалифицированных сертификатах организаций CN — это организация,
   а человек — в SN (фамилия) и G (имя и отчество) */
function разобратьИмя(s){
  const поля = {};
  for(const м of String(s || '').matchAll(/(?:^|,\s*)([A-Za-z.0-9]+)=("(?:[^"]|"")*"|[^,]*)/g)) поля[м[1].toUpperCase()] = м[2].replace(/^"|"$/g, '').replace(/""/g, '"').trim();
  const человек = поля.SN ? (поля.SN + ' ' + (поля.G || '')).trim() : (поля.CN || String(s || '').trim());
  const орг = поля.O && поля.O !== человек ? поля.O : (поля.SN && поля.CN && поля.CN !== человек ? поля.CN : '');
  return {человек, орг};
}
const подписьСерт = с => { const и = разобратьИмя(с.владелец); return и.человек + (и.орг ? ' (' + и.орг + ')' : '') + ' — до ' + кДате(с.действителенДо); };

function Старт(){
  if(ВТАБЛИЦАХ){ панель.поле('втабл', true); панель.список('формат', ['xlsx', 'plsx', 'csv']); панель.поле('формат', 'xlsx'); }
  показатьЖурнал();
  return обновить(true);
}
async function Сертификаты(){ return обновить(false); }
async function обновить(тихо){
  try {
    сертификаты = await эп.сертификаты();
  } catch(e){
    сертификаты = [];
    панель.список('серт', []);
    панель.поле('оСерт', [{текст: e.message, цвет: ЖЁЛТЫЙ}, {текст: '\nУстановите средство криптозащиты (КриптоПро CSP) и «КриптоПро ЭЦП Browser plug-in», положите cadesplugin_api.js рядом со страницей приложения и нажмите «Обновить список».', цвет: СЕРЫЙ}]);
    if(!тихо) панель.сообщение(e.message);
    return;
  }
  const сейчас = Date.now();
  const годные = сертификаты.filter(с => !с.действителенДо || new Date(с.действителенДо).getTime() > сейчас);
  панель.список('серт', сертификаты.map(подписьСерт));
  const был = хранилище.взять('отпечаток', '');
  const выбор = сертификаты.find(с => с.отпечаток === был) || годные[0] || сертификаты[0];
  if(выбор) панель.поле('серт', подписьСерт(выбор));
  показатьСерт(выбор);
  if(!тихо) панель.сообщение('Сертификатов: ' + сертификаты.length + (сертификаты.length > годные.length ? ', из них просрочено ' + (сертификаты.length - годные.length) : ''));
}
function выбранный(){ const п = параметры({}); return сертификаты.find(с => подписьСерт(с) === п.серт) || null; }
function СертВыбран(){ const с = выбранный(); if(с) хранилище.положить('отпечаток', с.отпечаток); показатьСерт(с); }
function показатьСерт(с){
  if(!с){ панель.поле('оСерт', [{текст: 'В хранилище «Личное» нет сертификатов', цвет: ЖЁЛТЫЙ}]); return; }
  const и = разобратьИмя(с.владелец), просрочен = с.действителенДо && new Date(с.действителенДо).getTime() < Date.now();
  панель.поле('оСерт', [{текст: и.человек, жирный: true}, {текст: (и.орг ? '\n' + и.орг : '') + '\nИздатель: ' + (разобратьИмя(с.издатель).человек || '—') + '\nОтпечаток: ' + с.отпечаток},
    {текст: '\nДействителен до ' + кДате(с.действителенДо) + (просрочен ? ' — просрочен' : ''), цвет: просрочен ? КРАСНЫЙ : ЗЕЛЁНЫЙ}]);
}

/* ---------- подписать ---------- */
function имяФайла(формат){
  const имя = String((ВТАБЛИЦАХ ? книга.имя : документ.имя) || (ВТАБЛИЦАХ ? 'Книга' : 'Документ')).replace(/\.(docx|odt|plsd|txt|xlsx|plsx|csv|ods)$/i, '').replace(/[\\/:*?"<>|]/g, ' ').trim();
  return (имя || 'Документ') + '.' + формат;
}
async function Подписать(){ return безСбоя(async () => {
  const п = параметры({});
  if(!сертификаты.length) await обновить(false);
  const с = выбранный() || сертификаты[0];
  if(!с) throw new Error('Нет сертификата для подписи');
  if(с.действителенДо && new Date(с.действителенДо).getTime() < Date.now() && !(await диалог.вопрос('Сертификат просрочен (' + кДате(с.действителенДо) + '). Подпись им не будет действительной. Всё равно подписать?'))) return;
  const допустимые = ВТАБЛИЦАХ ? ['xlsx', 'plsx', 'csv'] : ['docx', 'odt', 'plsd'];
  const формат = допустимые.includes(п.формат) ? п.формат : допустимые[0];
  const присоед = /^Присоединённая/.test(п.вид || '');
  const и = разобратьИмя(с.владелец);
  if(!ВТАБЛИЦАХ && п.отметка) вставитьОтметку(с, и);
  const байты = ВТАБЛИЦАХ ? await книга.собрать(п.листы && книга.выделение ? {листы: [книга.выделение.лист], формат} : {формат}) : await документ.собрать(формат);
  const имя = имяФайла(формат);
  const подпись = await эп.подписать(байты, {отпечаток: с.отпечаток, вид: присоед ? 'присоединённая' : 'откреплённая', что: имя});
  let итог;
  if(присоед) итог = await файл.выгрузить(имя + '.sig', подпись);
  else if(п.архивом) итог = await файл.выгрузитьАрхив([{имя, байты}, {имя: имя + '.sig', байты: подпись}], имя.replace(/\.\w+$/, '') + ' (подписано)');
  else { итог = await файл.выгрузить(имя, байты); if(итог && итог.сохранено !== false) итог = await файл.выгрузить(имя + '.sig', подпись); }
  const сохранено = !(итог && итог.сохранено === false);
  записатьВЖурнал({когда: new Date().toISOString(), файл: имя, кто: и.человек, отпечаток: с.отпечаток, вид: присоед ? 'присоединённая' : 'откреплённая', сохранено});
  панель.сообщение(сохранено ? 'Подписано: ' + имя + ' — ' + и.человек + (присоед ? ' (присоединённая подпись в ' + имя + '.sig)' : ' (подпись — ' + имя + '.sig)') : 'Подписано, но сохранение отменено — файл подписи не записан');
}); }
function вставитьОтметку(с, и){
  /* отметка об электронной подписи (ГОСТ Р 7.0.97-2016, п. 5.23): слова, номер сертификата, владелец, срок */
  const ряды = [['ДОКУМЕНТ ПОДПИСАН ЭЛЕКТРОННОЙ ПОДПИСЬЮ'], ['Сертификат: ' + с.отпечаток], ['Владелец: ' + и.человек + (и.орг ? ', ' + и.орг : '')], ['Действителен до: ' + кДате(с.действителенДо)]];
  /* прежнюю отметку (подписывают второй раз) — заменяем */
  const блоки = документ.блоки;
  for(let i = блоки.length - 1; i >= Math.max(0, блоки.length - 4); i--) if(/^ДОКУМЕНТ ПОДПИСАН ЭЛЕКТРОННОЙ ПОДПИСЬЮ/.test(блоки[i].текст.trim())){ документ.удалить(i); break; }
  документ.вставитьВКонец(документ.таблица(ряды, {шапка: true}));
}

/* ---------- проверить ---------- */
const ПОДПИСИ = /\.(sig|p7s|sgn|p7m)$/i;
async function Проверить(){ return безСбоя(async () => {
  const ф = await файл.выбрать({несколько: true, зачем: 'документ и файл его подписи (.sig)'});
  if(!ф || !ф.length) return;
  const подписи = ф.filter(x => ПОДПИСИ.test(x.имя)), данные = ф.filter(x => !ПОДПИСИ.test(x.имя));
  if(!подписи.length) throw new Error('Среди выбранных нет файла подписи (.sig, .p7s, .sgn, .p7m)');
  const части = [];
  for(const s of подписи){
    const база = s.имя.replace(ПОДПИСИ, '');
    const пара = данные.find(x => x.имя === база) || данные.find(x => x.имя.replace(/\.\w+$/, '') === база.replace(/\.\w+$/, '')) || (подписи.length === 1 && данные.length === 1 ? данные[0] : null);
    const р = await эп.проверить(пара ? пара.байты : null, s.байты);
    if(части.length) части.push({текст: '\n\n'});
    части.push({текст: s.имя + (пара ? ' ↔ ' + пара.имя : ' (присоединённая)') + '\n', жирный: true});
    if(р.верна){
      const и = разобратьИмя(р.владелец);
      части.push({текст: '✓ Подпись верна', цвет: ЗЕЛЁНЫЙ, жирный: true}, {текст: '\nПодписал: ' + (и.человек || '—') + (и.орг ? ', ' + и.орг : '') + (р.время ? '\nВремя подписи: ' + кВремени(р.время) : '') + (р.отпечаток ? '\nСертификат: ' + р.отпечаток : '')});
    } else части.push({текст: '✗ Подпись не верна', цвет: КРАСНЫЙ, жирный: true}, {текст: '\n' + (р.причина || 'причина не названа') + (пара ? '' : '\nЕсли подпись откреплённая — выберите вместе с ней и сам документ.')});
  }
  панель.поле('итогПроверки', части);
  панель.сообщение('Проверено подписей: ' + подписи.length);
}); }

/* ---------- журнал ---------- */
function записатьВЖурнал(з){ const ж = хранилище.взять('журнал', []); ж.unshift(з); хранилище.положить('журнал', ж.slice(0, 50)); показатьЖурнал(ж); }
function показатьЖурнал(ж){ ж = ж || хранилище.взять('журнал', []); панель.список('журнал', ж.map(з => кВремени(з.когда) + ' · ' + з.файл + ' · ' + з.кто + (з.сохранено === false ? ' · не сохранено' : ''))); }
function ОчиститьЖурнал(){ хранилище.положить('журнал', []); показатьЖурнал([]); панель.сообщение('Журнал очищен'); }
